package com.masterclass.inventory.repository; import com.masterclass.inventory.entity.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.OffsetDateTime;import java.util.*; public interface SaleRepository extends JpaRepository<Sale,Long>{ @Query("select s from Sale s where s.saleDate between :from and :to") List<Sale> findSalesBetween(@Param("from") OffsetDateTime from, @Param("to") OffsetDateTime to); }
